/* MODULE kn08 · Bước 5 Chọn kênh · CRM, Zalo OA, email: kênh của khách cũ
   10 bài × 7 câu. Tập trung vào kênh và dữ liệu khách cũ. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn08', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn08-01', skill:'channel', read:'6 phút', t:'Danh sách 20.000 số điện thoại, bao nhiêu số thật sự dùng được?',
  situation:'Một chuỗi trà sữa ở Đà Nẵng tự hào có 20.000 số điện thoại khách trong file Excel sau ba năm. Khi gửi thử một đợt tin nhắn, chỉ 11.000 tin đến được máy, và vài chục người gọi lại hỏi vì sao cửa hàng có số của họ. Chủ chuỗi bắt đầu nghi ngờ con số 20.000.',
  concept:{ name:'Danh sách hợp lệ và có đồng ý',
    body:'Một liên hệ chỉ có giá trị khi hội đủ ba điều: <b>đúng</b> (số/email còn hoạt động, gõ không sai), <b>của đúng người</b> (không phải số của nhân viên nhập hộ), và <b>có đồng ý</b> nhận tin từ bạn cho mục đích đó. Danh sách lớn mà thiếu ba điều này vừa tốn tiền gửi vừa làm khách khó chịu. Thu thập đúng cách là hỏi ngay tại điểm chạm, nói rõ sẽ gửi gì, bao lâu một lần, và cho khách lựa chọn từ chối.' },
  example:'Chuỗi lọc lại: 3.000 số sai định dạng hoặc trùng, 6.000 số không còn nhận tin, 2.500 số nhân viên tự nhập mà khách không hề đồng ý. Còn lại 8.500 số sạch. Từ tháng sau, thu ngân hỏi: “Anh/chị có muốn nhận ưu đãi sinh nhật qua Zalo không, mỗi tháng tối đa hai tin?” — và chỉ ghi khi khách gật đầu.',
  takeaway:'Đếm liên hệ dùng được và có đồng ý, không đếm dòng trong file Excel.',
  apply:'Mở danh sách khách của bạn, lấy ngẫu nhiên 20 dòng. Nói trong 60 giây: bao nhiêu dòng bạn chắc chắn khách đã đồng ý nhận tin, và bằng chứng nằm ở đâu.',
  mistakes:['Khoe tổng số dòng trong danh sách như thể đó là tài sản.','Để nhân viên tự điền số cho đủ chỉ tiêu mà không hỏi khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong danh sách 20.000 số tích luỹ ba năm, phần nào thường gây hại nhiều nhất khi gửi tin?',
    options:[{k:'a',t:'Những số khách chưa từng đồng ý nhận tin từ cửa hàng'},{k:'b',t:'Những số của khách chỉ mua một lần duy nhất rồi thôi'},
             {k:'c',t:'Những số khách đã đổi nhà mạng sau vài năm sử dụng'},{k:'d',t:'Những số của khách ở ngoài thành phố nơi đặt cửa hàng'}],
    answer:'a', why:{a:'Đúng. Gửi cho người không đồng ý khiến họ khó chịu, báo xấu, và làm hỏng uy tín của cả kênh.',
      b:'Khách mua một lần vẫn có thể quay lại nếu họ đã đồng ý nhận tin.',
      c:'Đổi nhà mạng thường vẫn giữ số; đây không phải phần gây hại chính.',
      d:'Khách ở xa vẫn có thể mua online; vị trí không làm liên hệ trở nên có hại.'} },
  { type:'mcq', stem:'Bạn phải chọn cách thu số điện thoại ở quầy thu ngân cho tháng tới. Bạn chọn cách nào?',
    options:[{k:'a',t:'Giao chỉ tiêu mỗi ca 50 số, nhân viên tự điền nếu khách ngại đọc số'},{k:'b',t:'Hỏi khách, nói rõ sẽ gửi gì và bao lâu một lần, chỉ ghi khi khách đồng ý'},
             {k:'c',t:'Bắt buộc khách đọc số điện thoại mới được tính tiền để có dữ liệu đầy đủ'},{k:'d',t:'Mua thêm danh sách số điện thoại trong khu vực để bù cho số bị lọc'}],
    answer:'b', why:{a:'Chỉ tiêu cứng đẩy nhân viên nhập số ảo hoặc số của chính họ; danh sách phình ra nhưng rỗng.',
      b:'Đúng. Khách biết mình sẽ nhận gì nên ít chặn, và bạn có căn cứ rằng họ đã đồng ý.',
      c:'Ép buộc làm khách khó chịu và nhiều người sẽ đọc bừa một số cho xong.',
      d:'Số mua ngoài không có sự đồng ý với bạn; gửi tin cho họ là rủi ro cả về uy tín lẫn pháp lý.'} },
  { type:'calc', stem:'Danh sách có 20.000 dòng. Lọc ra 3.000 dòng sai hoặc trùng, 6.000 số không còn nhận tin, 2.500 số không có đồng ý. Còn lại bao nhiêu phần trăm danh sách ban đầu dùng được?',
    unit:'%', ans:42.5, tol:0.1, wrong:[[57.5,'SAI_TINH_TOAN'],[77.3,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Số dùng được = 20.000 − 3.000 − 6.000 − 2.500 = 8.500.','Tỉ lệ = 8.500 ÷ 20.000 = <b>42,5%</b>.'] },
  { type:'mcq', stem:'Một shop mỹ phẩm online đặt ô “Đồng ý nhận tin khuyến mãi” đã tick sẵn ở trang thanh toán. Vấn đề là gì?',
    options:[{k:'a',t:'Ô tick sẵn làm trang thanh toán dài hơn và giảm tỉ lệ chốt đơn'},{k:'b',t:'Khách sẽ nhận quá nhiều hoá đơn điện tử trong hộp thư của họ'},
             {k:'c',t:'Khách không chủ động chọn, nên sự đồng ý đó rất yếu'},{k:'d',t:'Shop sẽ không thu được email của những khách đặt hàng qua điện thoại'}],
    answer:'c', why:{a:'Một ô tick hầu như không ảnh hưởng tỉ lệ chốt đơn; vấn đề nằm ở chất lượng sự đồng ý.',
      b:'Hoá đơn là tin giao dịch, khác với tin khuyến mãi mà ô này nói tới.',
      c:'Đúng. Đồng ý phải là hành động chủ động; tick sẵn khiến nhiều người không biết mình đã đăng ký.',
      d:'Đây là chuyện kênh đặt hàng khác, không liên quan tới ô tick.'} },
  { type:'mcq', stem:'Câu nào nên nói khi xin số của khách tại quầy để khách dễ đồng ý thật lòng?',
    options:[{k:'a',t:'Chị cho em xin số để hệ thống lưu thông tin khách hàng nhé'},{k:'b',t:'Chị đọc số giúp em, bên em cần số để xuất hoá đơn cho đúng quy định'},
             {k:'c',t:'Chị cho em số để bên em gửi thật nhiều ưu đãi hấp dẫn hằng ngày'},{k:'d',t:'Chị muốn nhận quà sinh nhật qua Zalo không, mỗi tháng tối đa hai tin'}],
    answer:'d', why:{a:'Câu này không nói khách sẽ nhận gì, nên khách không biết mình đồng ý với điều gì.',
      b:'Mượn lý do hoá đơn để lấy số gửi quảng cáo là đánh tráo mục đích, khách sẽ thấy bị lừa.',
      c:'“Hằng ngày” là lời hứa làm phiền; khách hoặc từ chối hoặc chặn sau vài tin.',
      d:'Đúng. Nói rõ lợi ích, kênh và tần suất — khách đồng ý với một điều cụ thể.'} },
  { type:'mcq', stem:'Sau khi lọc, danh sách còn 8.500 số. Chủ chuỗi lo vì “mất” 11.500 số. Nhận định nào đúng?',
    options:[{k:'a',t:'Số bị lọc là khách tiềm năng, nên giữ lại gửi thưa hơn cho đỡ phí'},{k:'b',t:'Chỉ mất danh sách ảo; chi phí gửi giảm và tỉ lệ phản hồi thật tăng'},
             {k:'c',t:'Nên gửi thêm một đợt cho 11.500 số rồi mới quyết định xoá hay giữ'},{k:'d',t:'Lọc như vậy là quá tay; chỉ nên bỏ những số sai định dạng mà thôi'}],
    answer:'b', why:{a:'Số không nhận tin hoặc không đồng ý không phải khách tiềm năng của kênh này; gửi thưa vẫn là gửi sai.',
      b:'Đúng. 11.500 số đó chưa bao giờ là tài sản; bỏ đi giúp đo đúng và tiết kiệm.',
      c:'Gửi thêm cho người không đồng ý chỉ tăng rủi ro bị báo xấu.',
      d:'Số không đồng ý cũng gây hại như số sai; giữ lại là tự làm bẩn danh sách.'} },
  { type:'mcq', stem:'Tình huống mới: một phòng gym muốn gom email hội viên. Cách nào cho danh sách sạch nhất?',
    options:[{k:'a',t:'Chép email từ các bình luận trên fanpage của phòng gym vào danh sách'},{k:'b',t:'Mua gói email “người quan tâm thể hình” từ một bên cung cấp dữ liệu'},
             {k:'c',t:'Để hội viên tự nhập email khi đăng ký gói tập, gửi mail xác nhận'},{k:'d',t:'Nhờ lễ tân ghi email theo trí nhớ khi hội viên trò chuyện ở quầy'}],
    answer:'c', why:{a:'Người bình luận chưa đồng ý nhận email; chép thông tin công khai không phải là xin phép.',
      b:'Danh sách mua ngoài không có quan hệ và không có đồng ý với phòng gym.',
      c:'Đúng. Khách tự nhập và bấm xác nhận nghĩa là email đúng và có đồng ý.',
      d:'Ghi theo trí nhớ dễ sai chính tả, email không tới được và không có bằng chứng đồng ý.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn08-02', skill:'insight', read:'7 phút', t:'Nên nhắn ai trước khi chỉ có ngân sách cho 1.000 tin?',
  situation:'Một cửa hàng giày ở TP.HCM có 6.000 khách cũ trong phần mềm bán hàng và ngân sách chỉ đủ gửi 1.000 tin Zalo cho đợt hàng mới. Nhân viên đề xuất gửi ngẫu nhiên. Chủ cửa hàng muốn biết có cách chọn thông minh hơn không.',
  concept:{ name:'Phân nhóm RFM',
    body:'RFM chấm mỗi khách theo ba trục: <b>R</b> (Recency) — lần mua gần nhất cách đây bao lâu; <b>F</b> (Frequency) — mua bao nhiêu lần; <b>M</b> (Monetary) — tổng chi bao nhiêu. Khách vừa mua gần đây, mua nhiều lần, chi nhiều là nhóm dễ phản hồi nhất. Khách lâu không mua nhưng từng chi nhiều là nhóm cần đánh thức. RFM không cần phần mềm đắt tiền: một bảng tính với ba cột là đủ bắt đầu.' },
  example:'Cửa hàng chia mỗi trục thành cao/thấp. Nhóm “R cao, F cao” có 800 khách; nhóm “R thấp, M cao” có 400 khách. Gửi 800 tin cho nhóm trung thành về mẫu mới, 200 tin còn lại cho nhóm chi nhiều nhưng lâu không quay lại kèm lời mời thử. Kết quả: 96 đơn, gấp ba lần đợt gửi ngẫu nhiên trước đó với cùng số tin.',
  takeaway:'Khi ngân sách tin có hạn, chọn người nhận bằng lần mua gần nhất, tần suất và giá trị.',
  apply:'Lấy 30 khách gần nhất trong sổ bán hàng. Nói trong 60 giây: năm khách nào bạn sẽ nhắn đầu tiên và vì sao, dựa trên R, F, M.',
  mistakes:['Chỉ nhìn tổng chi tiêu mà quên khách đã bỏ đi từ lâu.','Gửi cùng một thông điệp cho mọi nhóm RFM.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong ba trục R, F, M, trục nào thường dự đoán tốt nhất ai sẽ mở tin và mua tiếp?',
    options:[{k:'a',t:'M — người chi nhiều tiền nhất luôn là người mua lại nhanh nhất'},{k:'b',t:'F — người mua nhiều lần nhất, bất kể lần cuối đã cách bao lâu'},
             {k:'c',t:'Không trục nào, vì mua hay không phụ thuộc hoàn toàn vào khuyến mãi'},{k:'d',t:'R — người vừa mua gần đây thường phản hồi nhanh hơn hẳn'}],
    answer:'d', why:{a:'Người chi nhiều mà đã bỏ đi một năm vẫn khó phản hồi; M quan trọng nhưng không đứng một mình.',
      b:'Tần suất cao trong quá khứ mà nay đã ngừng hẳn thì chưa chắc còn quan tâm.',
      c:'Khuyến mãi có tác động, nhưng thói quen mua gần đây vẫn là tín hiệu mạnh.',
      d:'Đúng. Khách còn nhớ bạn và trải nghiệm còn tươi nên dễ phản hồi nhất.'} },
  { type:'mcq', stem:'Bạn có 1.000 tin và 6.000 khách. Bạn chọn cách gửi nào?',
    options:[{k:'a',t:'Gửi cho 1.000 khách chi nhiều nhất từ trước tới nay, bất kể lần cuối'},{k:'b',t:'Gửi ngẫu nhiên 1.000 khách để công bằng với mọi khách hàng cũ'},
             {k:'c',t:'Ưu tiên nhóm mua gần, mua đều; phần dư mời nhóm chi nhiều nhưng lâu vắng'},{k:'d',t:'Gửi cho 1.000 khách mới nhất vì họ còn nhớ cửa hàng rõ nhất'}],
    answer:'c', why:{a:'Nhiều khách chi nhiều đã ngừng mua từ lâu; chỉ nhìn M sẽ phí tin.',
      b:'Ngẫu nhiên bỏ qua thông tin bạn đang có về hành vi mua.',
      c:'Đúng. Kết hợp R, F, M để dồn tin vào nhóm dễ phản hồi và nhóm đáng cứu.',
      d:'Khách mới nhất có R cao nhưng có thể chỉ mua một lần giá thấp; chỉ dùng R là thiếu.'} },
  { type:'calc', stem:'Gửi 1.000 tin theo RFM được 96 đơn. Đợt trước gửi ngẫu nhiên 1.000 tin được 32 đơn. Tỉ lệ ra đơn tăng bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:6.4, tol:0.05, wrong:[[200,'NHAM_DIEM_PHAN_TRAM'],[64,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ RFM = 96 ÷ 1.000 = 9,6%. Tỉ lệ ngẫu nhiên = 32 ÷ 1.000 = 3,2%.','Chênh lệch = 9,6 − 3,2 = <b>6,4 điểm phần trăm</b> (còn tăng tương đối là 200%).'] },
  { type:'mcq', stem:'Khách A mua 8 lần, tổng 12 triệu, lần cuối cách đây 14 tháng. Nên xếp A vào nhóm nào?',
    options:[{k:'a',t:'Khách giá trị cao đang ngủ quên — cần một lời mời riêng để quay lại'},{k:'b',t:'Khách trung thành nhất, cứ gửi tin mẫu mới như mọi khách thân thiết khác'},
             {k:'c',t:'Khách đã mất hẳn, nên xoá khỏi danh sách để tiết kiệm chi phí gửi tin'},{k:'d',t:'Khách mới, vì hệ thống chỉ ghi nhận lần mua gần nhất của khách mà thôi'}],
    answer:'a', why:{a:'Đúng. F và M cao nhưng R thấp: đáng cứu, nhưng cần thông điệp khác nhóm đang mua đều.',
      b:'14 tháng không mua thì không còn là “đang trung thành”; tin mẫu mới chung chung dễ bị bỏ qua.',
      c:'Khách từng chi 12 triệu là người đáng thử đánh thức trước khi bỏ.',
      d:'Khách có 8 lần mua trong lịch sử, không phải khách mới.'} },
  { type:'mcq', stem:'Một quán cà phê có dữ liệu tích điểm nhưng không ghi số tiền mỗi lần. Họ làm RFM thế nào?',
    options:[{k:'a',t:'Chưa thể làm RFM, phải đợi đổi sang phần mềm có ghi đủ số tiền'},{k:'b',t:'Chỉ dùng M ước lượng theo giá ly trung bình rồi bỏ qua hai trục kia'},
             {k:'c',t:'Dùng R và F trước; M ước bằng số lần nhân giá trung bình một ly'},{k:'d',t:'Gọi điện hỏi từng khách tổng chi tiêu của họ tại quán trong năm qua'}],
    answer:'c', why:{a:'Chờ dữ liệu hoàn hảo làm mất thời gian; R và F đã đủ để phân nhóm hữu ích.',
      b:'Bỏ R và F là bỏ hai trục có dữ liệu thật để giữ trục ước lượng.',
      c:'Đúng. Với quán giá gần đồng đều, F nhân giá trung bình là ước lượng M chấp nhận được.',
      d:'Khách không nhớ chính xác và cuộc gọi như vậy gây phiền.'} },
  { type:'mcq', stem:'Nhóm “R cao, F thấp, M thấp” (vừa mua lần đầu, đơn nhỏ) nên nhận thông điệp gì?',
    options:[{k:'a',t:'Lời mời khôi phục kèm mã giảm sâu vì họ có nguy cơ bỏ đi ngay'},{k:'b',t:'Gợi ý lần mua thứ hai phù hợp với món vừa mua, không cần giảm sâu'},
             {k:'c',t:'Tin cảm ơn khách VIP kèm quà tặng cao cấp để giữ chân lâu dài'},{k:'d',t:'Không gửi gì, chờ họ tự quay lại rồi mới đưa vào nhóm để chăm sóc'}],
    answer:'b', why:{a:'Họ vừa mua, chưa phải nhóm ngủ quên; giảm sâu lúc này là phí biên lãi.',
      b:'Đúng. Việc cần làm với khách mới là biến lần một thành lần hai bằng gợi ý liên quan.',
      c:'Gọi khách mua một đơn nhỏ là VIP thì lãng phí quà và nghe không thật.',
      d:'Khoảng thời gian sau lần mua đầu là lúc dễ tạo thói quen nhất; im lặng là bỏ lỡ.'} },
  { type:'mcq', stem:'Sau khi làm RFM, bạn thấy 70% doanh thu năm qua đến từ 15% khách. Việc hợp lý tiếp theo là gì?',
    options:[{k:'a',t:'Bỏ hẳn 85% khách còn lại vì họ gần như không đóng góp gì'},{k:'b',t:'Giảm giá mạnh cho 85% khách còn lại để họ chi tiêu bằng nhóm trên'},
             {k:'c',t:'Dồn toàn bộ ngân sách quảng cáo tìm khách mới cho giống nhóm 15%'},{k:'d',t:'Tìm hiểu nhóm 15% mua gì, qua kênh nào, để giữ và nhân rộng'}],
    answer:'d', why:{a:'Nhóm 85% vẫn là nguồn để một phần lớn lên; bỏ hẳn là quá tay.',
      b:'Giảm giá đại trà không biến khách thỉnh thoảng thành khách trung thành.',
      c:'Tìm khách mới giống nhóm tốt là ý hay, nhưng trước hết phải hiểu nhóm đó là ai.',
      d:'Đúng. Hiểu nhóm tạo doanh thu chính giúp bảo vệ họ và biết tìm thêm người giống họ.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn08-03', skill:'channel', read:'7 phút', t:'Zalo OA, SMS hay email: kênh nào rẻ hơn cho mỗi đơn?',
  situation:'Một thương hiệu nến thơm bán online có 10.000 khách đồng ý nhận tin. Báo giá: SMS thương hiệu khoảng 800 đồng/tin, tin Zalo OA khoảng 300 đồng/tin, email gần như 0 đồng/tin ngoài phí công cụ 1,5 triệu/tháng. Chủ shop định chọn email vì “rẻ nhất”.',
  concept:{ name:'Chi phí trên mỗi đơn, không phải trên mỗi tin',
    body:'Mỗi kênh có giá gửi và tỉ lệ đọc khác nhau. SMS gần như ai cũng thấy nhưng đắt và ngắn chữ. Zalo OA rẻ hơn, có hình và nút bấm, nhưng khách phải quan tâm OA hoặc đủ điều kiện nhận. Email rẻ nhất mỗi tin nhưng nhiều người ít mở hộp thư. Cách so đúng là tính <b>chi phí trên mỗi đơn</b> = tổng chi phí gửi ÷ số đơn tạo ra, trên cùng một thông điệp.' },
  example:'Gửi thử 2.000 khách mỗi kênh. Email: mở 15%, 10 đơn, chi phí 1,5 triệu → 150.000 đồng/đơn. Zalo OA: mở 60%, 36 đơn, chi phí 600.000 → khoảng 16.700 đồng/đơn. SMS: 20 đơn, chi phí 1,6 triệu → 80.000 đồng/đơn. Kênh đắt mỗi tin chưa chắc đắt mỗi đơn; kênh rẻ mỗi tin chưa chắc rẻ mỗi đơn.',
  takeaway:'So kênh bằng chi phí trên mỗi đơn cùng một thông điệp, không bằng giá mỗi tin.',
  apply:'Chọn hai kênh bạn đang dùng. Nói trong 60 giây: mỗi kênh tốn bao nhiêu một tháng và mang về bao nhiêu đơn đo được.',
  mistakes:['Chọn kênh chỉ vì giá mỗi tin thấp nhất.','So kênh bằng hai thông điệp khác nhau rồi kết luận kênh nào tốt.'],
  q:[
  { type:'mcq', stem:'Đoán trước: kênh có giá mỗi tin rẻ nhất thường cũng là kênh có chi phí mỗi đơn rẻ nhất?',
    options:[{k:'a',t:'Đúng vậy, vì chi phí mỗi đơn luôn tỉ lệ thuận với giá mỗi tin gửi đi'},{k:'b',t:'Không chắc, vì tỉ lệ đọc và mua mỗi kênh khác nhau rất nhiều'},
             {k:'c',t:'Đúng, chỉ trừ khi thông điệp gửi đi có kèm mã giảm giá riêng'},{k:'d',t:'Sai, kênh đắt nhất mỗi tin luôn là kênh hiệu quả nhất mỗi đơn'}],
    answer:'b', why:{a:'Chi phí mỗi đơn còn phụ thuộc số người đọc và mua, không chỉ giá gửi.',
      b:'Đúng. Giá mỗi tin chỉ là một nửa phép tính; nửa còn lại là bao nhiêu tin biến thành đơn.',
      c:'Mã giảm giá thay đổi tỉ lệ mua ở mọi kênh, không làm quy tắc trên đúng hơn.',
      d:'Đắt nhất cũng không tự động hiệu quả nhất; phải đo.'} },
  { type:'mcq', stem:'Bạn phải chọn kênh chính cho tin ra mắt mùi nến mới. Bạn làm gì?',
    options:[{k:'a',t:'Gửi thử cùng thông điệp cho 2.000 khách mỗi kênh, so chi phí trên đơn'},{k:'b',t:'Chọn email ngay vì phí gửi gần như bằng không, tiết kiệm được nhiều nhất'},
             {k:'c',t:'Chọn SMS vì gần như ai cũng đọc tin nhắn điện thoại của mình'},{k:'d',t:'Gửi cả ba kênh cùng lúc cho toàn bộ 10.000 khách để phủ tối đa'}],
    answer:'a', why:{a:'Đúng. Thử nhỏ cùng thông điệp cho con số so sánh được trước khi chi lớn.',
      b:'Giá mỗi tin thấp nhưng nếu ít người mở thì chi phí mỗi đơn có thể cao nhất.',
      c:'Đọc nhiều không có nghĩa là mua nhiều; SMS còn đắt mỗi tin.',
      d:'Gửi ba kênh một lúc khiến khách nhận ba tin giống nhau và bạn không biết kênh nào tạo đơn.'} },
  { type:'calc', stem:'Zalo OA gửi 2.000 tin, mỗi tin 300 đồng, tạo 36 đơn. Chi phí trên mỗi đơn là bao nhiêu đồng (làm tròn tới hàng đơn vị)?',
    unit:'đồng', ans:16667, tol:5, wrong:[[300,'SAI_MAU_SO'],[600000,'QUEN_TI_LE_CHUYEN_DOI']], errors:['SAI_MAU_SO','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Tổng chi phí = 2.000 × 300 = 600.000 đồng.','Chi phí mỗi đơn = 600.000 ÷ 36 ≈ <b>16.667 đồng</b>.'] },
  { type:'mcq', stem:'Email có tỉ lệ mở 15%, Zalo OA 60%. Điều nào suy ra được chắc chắn?',
    options:[{k:'a',t:'Zalo OA sẽ luôn mang về gấp bốn lần doanh thu so với email'},{k:'b',t:'Nên bỏ hẳn email vì khách của shop không còn dùng hộp thư nữa'},
             {k:'c',t:'Nhiều người thấy tin Zalo hơn; mua hay không vẫn phải đo riêng'},{k:'d',t:'Email đang bị lỗi kỹ thuật vì tỉ lệ mở chuẩn phải trên 50%'}],
    answer:'c', why:{a:'Tỉ lệ mở không tự nhân thành doanh thu; tỉ lệ bấm và mua có thể khác.',
      b:'15% vẫn là một nhóm đọc; một số khách thích email hơn.',
      c:'Đúng. Mở là bước đầu của phễu; phải xem tiếp bấm và mua.',
      d:'Không có mức chuẩn chung như vậy; 15% có thể là bình thường với nhiều ngành.'} },
  { type:'mcq', stem:'Tin cần gửi là mã xác nhận đơn hàng và thời gian giao. Kênh nào hợp lý nhất?',
    options:[{k:'a',t:'Email bản tin tuần, gộp chung với các ưu đãi đang chạy của shop'},{k:'b',t:'Bài đăng trên fanpage, nhắc khách vào xem mục thông báo giao hàng'},
             {k:'c',t:'Tin Zalo OA dạng quảng cáo có ảnh sản phẩm và mã giảm giá lần sau'},{k:'d',t:'Tin giao dịch qua Zalo hoặc SMS, ngắn gọn, gửi ngay khi đơn tạo'}],
    answer:'d', why:{a:'Thông tin giao hàng cần tới ngay và riêng, không chờ bản tin tuần.',
      b:'Fanpage công khai, không cá nhân và khách dễ không thấy.',
      c:'Trộn quảng cáo vào tin giao dịch làm khách mất tin tưởng và dễ chặn.',
      d:'Đúng. Tin giao dịch cần nhanh, chắc tới tay, không kèm quảng cáo.'} },
  { type:'mcq', stem:'Tình huống mới: công ty phần mềm kế toán bán cho doanh nghiệp nhỏ muốn gửi hướng dẫn dài có bảng biểu. Kênh chính nên là?',
    options:[{k:'a',t:'Email, vì nội dung dài, cần lưu lại và đọc trên máy tính'},{k:'b',t:'SMS, vì gần như ai cũng đọc tin nhắn ngay khi điện thoại rung'},
             {k:'c',t:'Zalo OA, vì tỉ lệ mở cao nhất trong cả ba kênh đang có'},{k:'d',t:'Gọi điện cho từng khách để đọc hướng dẫn qua điện thoại'}],
    answer:'a', why:{a:'Đúng. Nội dung dài, cần tra lại, đọc lúc làm việc — đúng sở trường của email.',
      b:'SMS giới hạn độ dài, không có bảng biểu.',
      c:'Tỉ lệ mở cao không bù được việc nội dung dài khó đọc trên khung chat.',
      d:'Gọi điện tốn công và khách không lưu lại được hướng dẫn.'} },
  { type:'mcq', stem:'Email chi phí mỗi đơn 150.000 đồng, Zalo OA 16.700 đồng. Quyết định nào hợp lý?',
    options:[{k:'a',t:'Bỏ ngay email, chuyển toàn bộ khách sang nhận qua Zalo OA từ tháng sau'},{k:'b',t:'Tăng tần suất email lên gấp đôi để kéo chi phí mỗi đơn xuống thấp hơn'},
             {k:'c',t:'Dồn tin bán hàng về Zalo; giữ email cho nội dung dài, xem lại sau'},{k:'d',t:'Giữ nguyên như cũ vì chỉ gửi thử một lần thì chưa nói lên được gì'}],
    answer:'c', why:{a:'Có khách chỉ đồng ý nhận email; chuyển kênh cần sự đồng ý mới.',
      b:'Gửi dày hơn thường làm tỉ lệ mở giảm, và chi phí công cụ không giảm.',
      c:'Đúng. Dùng mỗi kênh cho việc nó làm tốt, và theo dõi thêm vài đợt để chắc.',
      d:'Chênh lệch gần 9 lần là đủ lớn để điều chỉnh, dù vẫn nên đo tiếp.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn08-04', skill:'channel', read:'6 phút', t:'Nhắn mỗi ngày thì bán thêm hay bị chặn thêm?',
  situation:'Một shop quần áo trẻ em tăng từ 2 lên 7 tin Zalo OA mỗi tuần vì “tin nào cũng ra vài đơn”. Sau một tháng, số người bỏ quan tâm OA tăng vọt, và tổng đơn từ Zalo không tăng mà còn giảm nhẹ.',
  concept:{ name:'Tần suất và tỉ lệ huỷ theo dõi',
    body:'Mỗi tin thêm có thể mang về vài đơn, nhưng cũng làm một số người bỏ quan tâm hoặc chặn. Người đã chặn thì không bao giờ nhận được tin nữa — đó là mất vĩnh viễn một phần danh sách. Vì vậy cần theo dõi cùng lúc <b>đơn mỗi tin</b> và <b>tỉ lệ huỷ theo dõi mỗi tin</b>. Tần suất hợp lý là mức mà tổng đơn trong tháng còn tăng trong khi danh sách không co lại nhanh. Gửi thứ khách cần, không gửi vì lịch đăng.' },
  example:'Trước: 2 tin/tuần, 8.000 người theo dõi, mỗi tin 0,2% huỷ, 40 đơn/tin → khoảng 320 đơn/tháng. Sau: 7 tin/tuần, mỗi tin 1% huỷ và chỉ 10 đơn/tin vì khách chai. Một tháng mất hơn 2.000 người theo dõi; đơn tháng khoảng 280. Shop quay về 3 tin/tuần, mỗi tin có một lý do rõ: hàng mới, size về lại, ưu đãi cuối tuần.',
  takeaway:'Mỗi tin phải xứng với cái giá có thể mất một người theo dõi.',
  apply:'Xem 10 tin gần nhất bạn gửi. Nói trong 60 giây: tin nào khách thật sự cần, tin nào gửi chỉ vì tới lịch.',
  mistakes:['Chỉ đếm đơn mỗi tin mà không đếm người bỏ theo dõi.','Nghĩ khách không chặn thì là khách không phiền.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tăng tin từ 2 lên 7 mỗi tuần thì tổng đơn tháng thường thế nào?',
    options:[{k:'a',t:'Tăng gần gấp 3,5 lần vì số tin gửi đi tăng gấp 3,5 lần'},{k:'b',t:'Tăng đều theo số tin, chỉ chậm lại một chút sau vài tháng'},
             {k:'c',t:'Tăng ít hoặc giảm, vì đơn mỗi tin giảm và người bỏ đi tăng'},{k:'d',t:'Giữ nguyên, vì khách chỉ mua theo nhu cầu chứ không theo tin'}],
    answer:'c', why:{a:'Đơn không nhân tuyến tính theo tin; khách chai và bỏ đi.',
      b:'Hiệu quả mỗi tin giảm khá nhanh, không phải sau vài tháng mới chậm.',
      c:'Đúng. Hai lực ngược chiều: đơn mỗi tin giảm và danh sách co lại.',
      d:'Tin có tác động tới việc mua; nó không vô hiệu, chỉ là quá nhiều thì phản tác dụng.'} },
  { type:'mcq', stem:'Bạn là chủ shop sau tháng gửi 7 tin/tuần. Bạn sửa gì?',
    options:[{k:'a',t:'Giữ 7 tin nhưng đổi sang giờ gửi khác để khách dễ đọc hơn'},{k:'b',t:'Dừng hẳn Zalo OA một tháng cho khách quên rồi gửi lại như cũ'},
             {k:'c',t:'Tăng mã giảm giá trong mỗi tin để bù cho đơn mỗi tin đang giảm'},{k:'d',t:'Giảm còn khoảng 3 tin, mỗi tin có lý do rõ khách cần biết'}],
    answer:'d', why:{a:'Giờ gửi không giải quyết việc khách thấy quá nhiều tin.',
      b:'Dừng hẳn làm mất nhịp với khách đang mua đều.',
      c:'Giảm giá nhiều hơn làm mỏng lãi và dạy khách chờ khuyến mãi.',
      d:'Đúng. Ít tin hơn nhưng mỗi tin đáng đọc thì giữ được danh sách và đơn.'} },
  { type:'calc', stem:'OA có 8.000 người theo dõi. Mỗi tin làm 1% số người đang theo dõi bỏ đi. Sau 4 tin liên tiếp còn lại khoảng bao nhiêu người (làm tròn tới hàng đơn vị)?',
    unit:'người', ans:7688, tol:2, wrong:[[7680,'RETENTION_TUYEN_TINH'],[320,'NHAM_SO_TUYET_DOI']], errors:['RETENTION_TUYEN_TINH','NHAM_SO_TUYET_DOI'],
    steps:['Mỗi tin giữ lại 99% số đang theo dõi.','8.000 × 0,99⁴ ≈ 8.000 × 0,9606 ≈ <b>7.688 người</b>.'] },
  { type:'mcq', stem:'Chỉ số nào báo sớm nhất rằng bạn đang nhắn quá dày?',
    options:[{k:'a',t:'Tỉ lệ huỷ theo dõi mỗi tin tăng dần qua các đợt gửi'},{k:'b',t:'Tổng doanh thu tháng này thấp hơn cùng kỳ tháng trước'},
             {k:'c',t:'Số bình luận dưới bài đăng fanpage giảm trong vài tuần qua'},{k:'d',t:'Chi phí gửi tin mỗi tháng tăng lên so với ngân sách ban đầu'}],
    answer:'a', why:{a:'Đúng. Huỷ theo dõi phản ứng ngay sau từng tin, trước khi doanh thu kịp thay đổi.',
      b:'Doanh thu chịu nhiều yếu tố và phản ứng chậm.',
      c:'Bình luận fanpage là kênh khác, không đo mức phiền của tin nhắn.',
      d:'Chi phí tăng là hệ quả của gửi nhiều, không cho biết khách có phiền không.'} },
  { type:'mcq', stem:'Tình huống mới: một nhà thuốc muốn nhắc khách mua lại thuốc dùng hằng tháng. Tần suất nào hợp lý?',
    options:[{k:'a',t:'Nhắn mỗi ngày để khách không bao giờ quên việc mua thuốc'},{k:'b',t:'Chỉ nhắn một lần duy nhất vào ngày sinh nhật của từng khách'},
             {k:'c',t:'Nhắn mỗi tuần một lần như lịch bản tin chung cho mọi khách'},{k:'d',t:'Nhắn một tin vài ngày trước khi hộp thuốc lần trước sắp hết'}],
    answer:'d', why:{a:'Nhắn hằng ngày gây phiền trong khi nhu cầu chỉ tới mỗi tháng.',
      b:'Sinh nhật không liên quan tới lúc hết thuốc.',
      c:'Lịch chung không khớp với chu kỳ dùng thuốc của từng người.',
      d:'Đúng. Tần suất theo nhu cầu của khách — tin tới đúng lúc thì không bị coi là phiền.'} },
  { type:'mcq', stem:'Một tin có 40 đơn nhưng làm 400 người bỏ theo dõi. Nhận định nào hợp lý?',
    options:[{k:'a',t:'Tin thành công vì 40 đơn là con số tốt cho một lần gửi tin'},{k:'b',t:'Cần cân đơn hôm nay với đơn tương lai mất theo 400 người đó'},
             {k:'c',t:'Người bỏ theo dõi là khách không có giá trị nên không cần quan tâm'},{k:'d',t:'Tin thất bại hoàn toàn, nên xoá mọi tin cùng chủ đề đã gửi'}],
    answer:'b', why:{a:'Chỉ nhìn đơn hôm nay bỏ qua cái giá dài hạn.',
      b:'Đúng. 400 người đó từng có thể mua nhiều lần; phải tính cả phần mất đi.',
      c:'Nhiều người bỏ theo dõi vì phiền, không phải vì họ không bao giờ mua.',
      d:'Một tin có vấn đề là để rút kinh nghiệm nội dung, không phải bỏ cả chủ đề.'} },
  { type:'mcq', stem:'Cách nào giúp khách ở lại khi họ thấy tin quá dày?',
    options:[{k:'a',t:'Ẩn nút huỷ theo dõi thật kỹ để khách khó tìm thấy mà bỏ đi'},{k:'b',t:'Gửi thêm tin xin lỗi mỗi khi có một người bỏ theo dõi OA'},
             {k:'c',t:'Cho khách chọn nhận ít hơn hoặc chỉ loại tin họ quan tâm'},{k:'d',t:'Tặng mã giảm giá cho mọi người để họ quên việc tin quá nhiều'}],
    answer:'c', why:{a:'Giấu lối ra khiến khách bực và chọn chặn, còn tệ hơn huỷ theo dõi.',
      b:'Thêm tin là thêm phiền.',
      c:'Đúng. Cho lựa chọn “ít hơn” giữ được người thay vì mất hẳn.',
      d:'Mã giảm giá không sửa được nguyên nhân gây phiền.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn08-05', skill:'comm', read:'6 phút', t:'Gọi tên khách trong tin là đủ cá nhân hoá chưa?',
  situation:'Một thương hiệu mỹ phẩm gửi Zalo “Chào chị Lan, ưu đãi dành riêng cho chị!” kèm mã giảm son cho toàn bộ 15.000 khách, kể cả khách chỉ mua kem chống nắng cho chồng. Một đợt khác, họ nhắc chính xác “chị vừa xem kem nền màu 02 lúc 23 giờ hôm qua” và bị khách phàn nàn là đáng sợ.',
  concept:{ name:'Cá nhân hoá đúng mức',
    body:'Cá nhân hoá có ích khi nó làm tin <b>liên quan hơn</b>: gợi ý đúng thứ khách dùng, đúng lúc họ cần. Chỉ chèn tên vào tin chung thì không đổi được gì. Ngược lại, nhắc quá chi tiết điều khách không nghĩ bạn biết — giờ họ xem, món họ tìm — khiến khách thấy bị theo dõi. Nguyên tắc: dùng dữ liệu khách <b>biết mình đã cho</b> (món đã mua, loại da đã khai) và nói ở mức tự nhiên như một người bán hàng tử tế.' },
  example:'Đợt sau, thương hiệu chia theo món đã mua: khách mua chống nắng nhận tin “kem chống nắng của chị dùng khoảng hai tháng là hết, bên em có size lớn tiết kiệm hơn”; khách khai da dầu nhận gợi ý sữa rửa mặt cho da dầu. Không nhắc giờ xem hay trang đã lướt. Tỉ lệ bấm tăng từ 2% lên 5%, lời phàn nàn gần như không còn.',
  takeaway:'Cá nhân hoá để tin liên quan hơn, dùng dữ liệu khách biết mình đã cho.',
  apply:'Viết lại một tin bạn vừa gửi cho hai nhóm khách khác nhau. Nói trong 60 giây: mỗi bản dùng dữ liệu gì của khách và vì sao khách thấy tự nhiên.',
  mistakes:['Chèn tên vào tin chung rồi gọi đó là cá nhân hoá.','Nhắc quá chi tiết hành vi lướt web làm khách thấy bị theo dõi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tin nào khách thấy liên quan nhất?',
    options:[{k:'a',t:'“Chào chị Lan, ưu đãi riêng cho chị” kèm mã giảm cho mọi món'},{k:'b',t:'Tin chung không tên nhưng có ảnh đẹp và mã giảm giá rất sâu'},
             {k:'c',t:'“Chị vừa xem kem nền 02 lúc 23 giờ, mua ngay kẻo hết nha chị”'},{k:'d',t:'Tin gợi ý size lớn cho món chị đã mua khi món đó sắp dùng hết'}],
    answer:'d', why:{a:'Tên thì cá nhân nhưng nội dung là tin chung.',
      b:'Mã sâu có thể kéo đơn nhưng không làm tin liên quan hơn.',
      c:'Quá chi tiết về hành vi làm khách thấy bị theo dõi.',
      d:'Đúng. Dựa vào món khách biết mình đã mua và đúng lúc cần.'} },
  { type:'mcq', stem:'Bạn có dữ liệu: món đã mua, loại da khách khai, và lịch sử lướt web chi tiết. Bạn chọn dùng gì cho tin tháng này?',
    options:[{k:'a',t:'Món đã mua và loại da khách khai; lịch sử lướt để gợi ý ngầm'},{k:'b',t:'Dùng hết cả ba loại dữ liệu và nói rõ trong tin để khách thấy hiểu mình'},
             {k:'c',t:'Chỉ dùng tên khách vì dữ liệu nào khác cũng có rủi ro bị phàn nàn'},{k:'d',t:'Chỉ dùng lịch sử lướt web vì đó là dữ liệu mới nhất về khách'}],
    answer:'a', why:{a:'Đúng. Dữ liệu khách biết mình đã cho có thể nói thẳng; hành vi lướt chỉ nên dùng để chọn gợi ý, không nhắc ra.',
      b:'Nói thẳng hành vi lướt web khiến khách khó chịu.',
      c:'Bỏ hết dữ liệu hữu ích làm tin trở lại thành tin chung.',
      d:'Lướt web là tín hiệu yếu và nhạy cảm nhất khi nhắc ra.'} },
  { type:'calc', stem:'Gửi 15.000 tin. Bản chung có tỉ lệ bấm 2%, bản cá nhân hoá theo món đã mua 5%. Bản cá nhân hoá có thêm bao nhiêu lượt bấm?',
    unit:'lượt', ans:450, tol:0, wrong:[[3,'NHAM_DIEM_PHAN_TRAM'],[750,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Bản chung: 15.000 × 2% = 300 lượt. Bản cá nhân: 15.000 × 5% = 750 lượt.','Thêm = 750 − 300 = <b>450 lượt</b>.'] },
  { type:'mcq', stem:'Khách mua kem chống nắng nam cho chồng liên tục nhận tin gợi ý son môi. Lỗi ở đâu?',
    options:[{k:'a',t:'Tin gửi sai giờ, lẽ ra nên gửi buổi tối khi khách rảnh'},{k:'b',t:'Mã giảm giá kèm theo quá thấp nên khách không muốn mua son'},
             {k:'c',t:'Hệ thống gán giới tính mặc định, không nhìn món khách đã mua'},{k:'d',t:'Khách này không thích mỹ phẩm, nên xoá khỏi danh sách nhận tin'}],
    answer:'c', why:{a:'Giờ gửi không phải vấn đề; nội dung không liên quan.',
      b:'Mã cao hơn cũng không làm son liên quan tới người mua đồ nam.',
      c:'Đúng. Đoán theo đặc điểm thay vì hành vi mua dẫn tới gợi ý sai.',
      d:'Khách vẫn mua đều kem chống nắng; họ chỉ cần gợi ý đúng món.'} },
  { type:'mcq', stem:'Tình huống mới: một hiệu sách online muốn cá nhân hoá. Cách nào đúng mức nhất?',
    options:[{k:'a',t:'Nhắc khách đã đọc tới trang bao nhiêu trong sách điện tử đã mua'},{k:'b',t:'Báo sách mới cùng tác giả hoặc thể loại khách đã từng mua trước đó'},
             {k:'c',t:'Gửi cùng một danh sách sách bán chạy nhất tuần cho mọi khách'},{k:'d',t:'Đoán tuổi khách qua ảnh đại diện Zalo rồi gợi ý sách theo tuổi'}],
    answer:'b', why:{a:'Nhắc chi tiết hành vi đọc dễ gây cảm giác bị theo dõi.',
      b:'Đúng. Dựa trên lịch sử mua khách biết rõ, và rất liên quan.',
      c:'Không có cá nhân hoá nào cả.',
      d:'Đoán từ ảnh đại diện vừa sai vừa xâm phạm.'} },
  { type:'mcq', stem:'Cá nhân hoá tới mức nào thì nên dừng?',
    options:[{k:'a',t:'Khi thêm chi tiết không làm tin liên quan hơn mà chỉ lộ dữ liệu'},{k:'b',t:'Không cần dừng, càng nhiều chi tiết về khách thì tin càng hiệu quả'},
             {k:'c',t:'Khi đã chia khách thành hơn năm nhóm khác nhau trong hệ thống'},{k:'d',t:'Khi chi phí phần mềm cá nhân hoá vượt quá một triệu mỗi tháng'}],
    answer:'a', why:{a:'Đúng. Ranh giới là giá trị cho khách, không phải số trường dữ liệu dùng được.',
      b:'Quá nhiều chi tiết làm khách sợ, không phải hiệu quả hơn.',
      c:'Số nhóm không phải thước đo đúng mức.',
      d:'Chi phí phần mềm là chuyện khác với việc khách có thấy thoải mái không.'} },
  { type:'mcq', stem:'Một khách phản hồi: “Sao em biết chị xem món đó lúc nửa đêm?”. Bạn nên làm gì?',
    options:[{k:'a',t:'Giải thích kỹ thuật cookie để khách hiểu đó là chuyện bình thường'},{k:'b',t:'Im lặng không trả lời để tránh làm chuyện lớn thêm trên mạng'},
             {k:'c',t:'Gửi mã giảm giá để làm dịu và mời khách mua món đó luôn'},{k:'d',t:'Xin lỗi, bỏ kiểu nhắc hành vi lướt web khỏi mọi tin sau này'}],
    answer:'d', why:{a:'Giải thích kỹ thuật không làm khách bớt cảm giác bị theo dõi.',
      b:'Im lặng khiến khách nghĩ bạn không tôn trọng họ.',
      c:'Dùng quà để lấp một lỗi về cảm giác riêng tư nghe như mua chuộc.',
      d:'Đúng. Nhận lỗi và sửa cách làm cho mọi khách, không chỉ một người.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn08-06', skill:'measure', read:'7 phút', t:'Chương trình tích điểm đang giữ khách hay chỉ đang tặng tiền?',
  situation:'Một chuỗi bánh mì ở Hà Nội ra thẻ tích điểm: mỗi 10.000 đồng được 1 điểm, 50 điểm đổi một ổ bánh 25.000 đồng. Sau sáu tháng có 12.000 thành viên. Kế toán hỏi: chương trình tốn bao nhiêu, và khách có mua nhiều hơn thật không, hay chỉ là khách vốn trung thành nay được tặng thêm?',
  concept:{ name:'Chương trình thành viên có mục tiêu',
    body:'Tích điểm là một kênh dữ liệu và một lời hứa với khách. Nó đáng làm khi <b>thay đổi hành vi</b>: khách quay lại nhanh hơn, mua thêm, hoặc chọn bạn thay vì quán bên cạnh. Cần tính <b>tỉ lệ thưởng</b> = giá trị quà ÷ số tiền phải chi để nhận quà, và so hành vi của thành viên với nhóm tương đương chưa tham gia. Ngoài ra, chương trình cho bạn số điện thoại có đồng ý — thường là giá trị lớn nhất.' },
  example:'Để đổi 1 ổ 25.000 đồng, khách chi 500.000 đồng → tỉ lệ thưởng 5%. So 1.000 thành viên với 1.000 khách tương tự chưa tham gia: thành viên ghé 3,2 lần/tháng, nhóm kia 2,6 lần. Phần tăng 0,6 lần/tháng là tác dụng thật; phần còn lại là khách vốn đã quay lại. Chuỗi giữ chương trình và gửi tin “còn 5 điểm nữa được bánh miễn phí” để kéo khách gần mốc.',
  takeaway:'Tích điểm đáng tiền khi khách thay đổi hành vi, không chỉ khi khách nhận quà.',
  apply:'Nếu bạn có (hoặc định làm) tích điểm, nói trong 60 giây: tỉ lệ thưởng bao nhiêu phần trăm và bạn so với nhóm nào để biết nó có tác dụng.',
  mistakes:['Đếm số thành viên đăng ký như thước đo thành công.','Quên rằng khách trung thành sẵn cũng nhận quà mà không đổi hành vi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: con số nào cho biết chương trình tích điểm có hiệu quả?',
    options:[{k:'a',t:'Tổng số thành viên đã đăng ký thẻ tích điểm sau sáu tháng'},{k:'b',t:'Tổng số điểm đã được phát ra cho khách trong cả chương trình'},
             {k:'c',t:'Chênh lệch tần suất mua giữa thành viên và nhóm tương đương'},{k:'d',t:'Số ổ bánh miễn phí đã được đổi thưởng tại mọi cửa hàng trong chuỗi'}],
    answer:'c', why:{a:'Đăng ký là dễ; không cho biết hành vi có đổi không.',
      b:'Điểm phát ra là chi phí, không phải kết quả.',
      c:'Đúng. So với nhóm tương đương mới tách được tác dụng thật của chương trình.',
      d:'Số quà đổi là chi phí; có thể đến từ khách vốn đã mua thường xuyên.'} },
  { type:'mcq', stem:'Bạn được giao thiết kế lại mốc đổi quà. Bạn chọn gì?',
    options:[{k:'a',t:'Hạ mốc xuống 10 điểm để khách đổi quà liên tục, vui vẻ hơn'},{k:'b',t:'Giữ tỉ lệ thưởng vừa phải, nhắc khách khi sắp chạm mốc quà'},
             {k:'c',t:'Nâng mốc lên 500 điểm để tiết kiệm chi phí quà cho chuỗi'},{k:'d',t:'Bỏ quà, chỉ giữ thẻ thành viên để thu thập số điện thoại khách'}],
    answer:'b', why:{a:'Mốc quá thấp đẩy tỉ lệ thưởng lên cao, chủ yếu tặng tiền cho khách vốn đã mua.',
      b:'Đúng. Mốc vừa tầm cộng lời nhắc gần mốc kéo khách quay lại sớm hơn.',
      c:'Mốc quá xa khiến khách bỏ cuộc, chương trình mất tác dụng.',
      d:'Không có lợi ích, khách không có lý do đưa số điện thoại.'} },
  { type:'calc', stem:'Mỗi 10.000 đồng được 1 điểm, 50 điểm đổi một ổ bánh trị giá 25.000 đồng. Tỉ lệ thưởng là bao nhiêu phần trăm?',
    unit:'%', ans:5, tol:0.05, wrong:[[50,'SAI_MAU_SO'],[0.5,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tiền phải chi để đủ 50 điểm = 50 × 10.000 = 500.000 đồng.','Tỉ lệ thưởng = 25.000 ÷ 500.000 = <b>5%</b>.'] },
  { type:'mcq', stem:'Thành viên ghé 3,2 lần/tháng, còn khách tương tự chưa tham gia 2,6 lần. Tác dụng thật của chương trình là?',
    options:[{k:'a',t:'Toàn bộ 3,2 lần/tháng, vì đó là hành vi của thành viên'},{k:'b',t:'Chưa kết luận được gì vì hai nhóm có số người bằng nhau'},
             {k:'c',t:'Khoảng 2,6 lần/tháng, vì đó là mức nền của nhóm so sánh'},{k:'d',t:'Khoảng 0,6 lần/tháng — phần chênh so với nhóm tương đương'}],
    answer:'d', why:{a:'Phần lớn 3,2 lần là khách vẫn sẽ ghé dù không có thẻ.',
      b:'Số người bằng nhau là điều kiện tốt để so, không phải lý do không kết luận.',
      c:'2,6 là mức nền, không phải tác dụng.',
      d:'Đúng. Chỉ phần chênh mới là thứ chương trình tạo ra.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng hàng không nội địa và một tiệm tạp hoá đầu ngõ. Ai cần chương trình tích điểm hơn?',
    options:[{k:'a',t:'Hãng bay, vì khách có nhiều lựa chọn và mỗi lần mua giá trị cao'},{k:'b',t:'Tiệm tạp hoá, vì khách ghé thường xuyên nên nhất định phải có thẻ'},
             {k:'c',t:'Cả hai như nhau vì mọi doanh nghiệp đều cần có thẻ thành viên'},{k:'d',t:'Không ai cần, vì khách chỉ chọn theo giá rẻ nhất tại thời điểm mua'}],
    answer:'a', why:{a:'Đúng. Giá trị mỗi lần mua lớn và dễ đổi hãng nên giữ khách có lợi rõ.',
      b:'Tiệm đầu ngõ đã có lợi thế gần nhà; tích điểm ít đổi hành vi.',
      c:'Không phải doanh nghiệp nào cũng cần; tuỳ việc nó có đổi hành vi không.',
      d:'Nhiều khách chọn theo tiện lợi và quen thuộc, không chỉ giá.'} },
  { type:'mcq', stem:'Sau một năm, điểm tồn chưa đổi trên sổ sách rất lớn. Điều đó có nghĩa gì?',
    options:[{k:'a',t:'Tin tốt thuần tuý: khách tích điểm mà không đổi nên chuỗi có lời'},{k:'b',t:'Một khoản nợ quà với khách, và dấu hiệu nhiều người đã quên thẻ'},
             {k:'c',t:'Chương trình đang rất thành công vì khách tích điểm quá nhiều'},{k:'d',t:'Cần xoá điểm tồn ngay mà không báo khách để làm sạch sổ sách'}],
    answer:'b', why:{a:'Điểm không đổi thường là khách hết quan tâm, không phải lời lãi.',
      b:'Đúng. Đó là nghĩa vụ với khách và cũng là tín hiệu chương trình không còn hấp dẫn.',
      c:'Tích nhiều mà không đổi cho thấy mốc có thể quá xa.',
      d:'Xoá điểm không báo làm mất lòng tin và có thể gây tranh chấp.'} },
  { type:'mcq', stem:'Nên dùng dữ liệu tích điểm để làm gì ngoài việc phát quà?',
    options:[{k:'a',t:'Bán lại danh sách thành viên cho các thương hiệu đối tác khác'},{k:'b',t:'Đăng tên các thành viên chi nhiều nhất lên fanpage để vinh danh'},
             {k:'c',t:'Phân nhóm theo lần mua và tần suất để nhắn đúng người đúng lúc'},{k:'d',t:'Tính lương thưởng nhân viên theo số thành viên mới mỗi ca làm'}],
    answer:'c', why:{a:'Bán dữ liệu vượt khỏi mục đích khách đã đồng ý.',
      b:'Công khai chi tiêu của khách mà không hỏi là xâm phạm riêng tư.',
      c:'Đúng. Dữ liệu mua của thành viên là nguồn chính để làm RFM và nhắn tin trúng hơn.',
      d:'Chỉ tiêu theo số đăng ký dễ sinh thẻ ảo và dữ liệu bẩn.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn08-07', skill:'channel', read:'6 phút', t:'Khách 6 tháng không quay lại: gọi dậy hay để yên?',
  situation:'Một spa ở Cần Thơ có 3.000 khách từng dùng dịch vụ nhưng đã hơn 6 tháng không đặt lịch. Chủ spa định gửi mã giảm 50% cho tất cả. Quản lý lo rằng làm vậy vừa lỗ vừa dạy khách chỉ quay lại khi có giảm sâu.',
  concept:{ name:'Chiến dịch đánh thức khách ngủ quên',
    body:'Khách ngủ quên là khách lâu không mua so với nhịp bình thường của ngành. Đánh thức nên đi theo <b>bậc thang</b>: tin đầu nhắc nhẹ và có lý do mới (dịch vụ mới, lịch trống), tin sau mới có ưu đãi vừa phải, tin cuối hỏi khách có muốn tiếp tục nhận tin không. Ai không phản hồi sau chuỗi này thì giảm tần suất hoặc ngừng gửi, để danh sách sạch và không bị chặn. Luôn tính lãi sau khi trừ ưu đãi, không chỉ đếm khách quay lại.' },
  example:'Spa gửi 3.000 khách: tin 1 giới thiệu liệu trình mới, 90 khách đặt lịch. Tin 2 cho người chưa đặt, ưu đãi 20%, thêm 150 khách. Tin 3 hỏi “chị có muốn tiếp tục nhận tin không?”, 400 người chọn ngừng. So với giảm 50% cho tất cả, chuỗi bậc thang mang về ít khách hơn một chút nhưng lãi cao hơn nhiều và danh sách sạch hơn.',
  takeaway:'Đánh thức theo bậc: lý do mới trước, ưu đãi vừa sau, rồi hỏi khách có muốn ở lại.',
  apply:'Chọn một nhóm khách lâu không mua của bạn. Nói trong 60 giây: ba tin đánh thức bạn sẽ gửi theo thứ tự nào, mỗi tin nói gì.',
  mistakes:['Mở màn bằng giảm giá sâu cho mọi khách ngủ quên.','Gửi mãi cho người không phản hồi, làm bẩn danh sách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tin đánh thức đầu tiên nên là gì?',
    options:[{k:'a',t:'Mã giảm 50% có hạn trong 24 giờ để tạo áp lực phải quay lại'},{k:'b',t:'Một lý do mới để quay lại, chưa cần ưu đãi lớn ngay từ đầu'},
             {k:'c',t:'Câu hỏi khách có muốn huỷ nhận tin không để làm sạch danh sách'},{k:'d',t:'Tin cảm ơn chung chung, không nêu gì cụ thể để tránh làm phiền'}],
    answer:'b', why:{a:'Giảm sâu ngay đầu làm lỗ với cả những khách vẫn quay lại mà không cần ưu đãi.',
      b:'Đúng. Nhiều khách chỉ cần một lời nhắc có lý do; giữ ưu đãi cho bước sau.',
      c:'Hỏi huỷ là bước cuối, không phải bước mở đầu.',
      d:'Tin không có nội dung thì không đánh thức được ai.'} },
  { type:'mcq', stem:'Bạn phải chọn phương án cho 3.000 khách ngủ quên của spa. Bạn chọn gì?',
    options:[{k:'a',t:'Giảm 50% cho cả 3.000 khách để kéo về nhiều khách nhất có thể'},{k:'b',t:'Gửi mỗi tuần một tin khuyến mãi mới cho tới khi khách quay lại'},
             {k:'c',t:'Chuỗi ba tin: lý do mới, ưu đãi vừa, rồi hỏi có muốn nhận tiếp'},{k:'d',t:'Xoá cả 3.000 khách vì đã sáu tháng không quay lại dùng dịch vụ'}],
    answer:'c', why:{a:'Nhiều khách mà lãi mỏng, và dạy khách chờ giảm sâu.',
      b:'Gửi dồn dập cho người không phản hồi dễ bị chặn.',
      c:'Đúng. Bậc thang giữ biên lãi và làm sạch danh sách.',
      d:'Nhiều khách chỉ cần một lời nhắc; xoá ngay là bỏ tiền trên bàn.'} },
  { type:'calc', stem:'Liệu trình giá 600.000 đồng, chi phí dịch vụ 300.000 đồng. Phương án giảm 50% kéo về 300 khách. Lãi gộp của phương án này là bao nhiêu đồng?',
    unit:'đồng', ans:0, tol:0, wrong:[[90000000,'GIAM_GIA_QUEN_BIEN'],[180000000,'QUEN_CHI_PHI_KHUYEN_MAI']], errors:['GIAM_GIA_QUEN_BIEN','QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Giá sau giảm 50% = 300.000 đồng; lãi mỗi khách = 300.000 − 300.000 = 0.','Lãi gộp = 300 × 0 = <b>0 đồng</b> — kéo khách về mà không lời đồng nào.'] },
  { type:'mcq', stem:'Nên định nghĩa “khách ngủ quên” thế nào?',
    options:[{k:'a',t:'Mọi khách không mua trong 30 ngày, áp dụng chung cho mọi ngành'},{k:'b',t:'Khách chưa từng mở bất kỳ tin nào mà cửa hàng đã gửi tới họ'},
             {k:'c',t:'Khách đã mua dưới ba lần trong toàn bộ lịch sử giao dịch'},{k:'d',t:'Khách lâu không mua so với nhịp mua bình thường của ngành đó'}],
    answer:'d', why:{a:'30 ngày là lâu với quán cà phê nhưng bình thường với nội thất.',
      b:'Không mở tin chưa chắc đã ngừng mua; họ có thể mua trực tiếp.',
      c:'Số lần mua ít là F thấp, không phải ngủ quên.',
      d:'Đúng. Mốc ngủ quên phải theo chu kỳ mua của ngành.'} },
  { type:'mcq', stem:'Tin cuối hỏi “Có muốn tiếp tục nhận tin không?” và 400 người chọn ngừng. Đánh giá thế nào?',
    options:[{k:'a',t:'Kết quả tốt: danh sách sạch hơn, số liệu đo sau này đúng hơn'},{k:'b',t:'Thất bại, vì chiến dịch đã làm mất 400 khách hàng tiềm năng'},
             {k:'c',t:'Nên gửi thêm tin thuyết phục 400 người này đổi ý ở lại'},{k:'d',t:'Không nên hỏi câu đó, vì nó nhắc khách rằng họ có thể rời đi'}],
    answer:'a', why:{a:'Đúng. Người không muốn nhận tin sẽ không mua qua kênh này; bỏ họ giúp tránh bị báo xấu.',
      b:'400 người đó đã ngừng quan tâm từ trước; câu hỏi chỉ làm rõ điều đó.',
      c:'Họ đã nói không; gửi tiếp là không tôn trọng lựa chọn.',
      d:'Giữ người muốn đi bằng cách không hỏi chỉ đẩy họ tới chặn.'} },
  { type:'mcq', stem:'Tình huống mới: một shop bán nệm, khách thường 5–7 năm mới mua lại. Chiến dịch “đánh thức sau 6 tháng” có hợp lý?',
    options:[{k:'a',t:'Hợp lý, vì sáu tháng là mốc ngủ quên chuẩn của mọi ngành hàng'},{k:'b',t:'Hợp lý, nhưng phải kèm giảm giá sâu vì nệm là món đắt tiền'},
             {k:'c',t:'Không hợp lý với nệm; nên nhắn về gối, ga, chăm sóc nệm'},{k:'d',t:'Không hợp lý, nên ngừng nhắn tin cho khách cho tới năm thứ năm'}],
    answer:'c', why:{a:'Không có mốc chuẩn chung; nệm có chu kỳ rất dài.',
      b:'Giảm giá không làm khách vừa mua nệm cần nệm mới.',
      c:'Đúng. Giữ liên lạc bằng món phụ có chu kỳ ngắn hơn, không ép mua nệm.',
      d:'Im lặng năm năm thì khách quên bạn khi cần mua lại.'} },
  { type:'mcq', stem:'Làm sao biết chiến dịch đánh thức thật sự tạo ra khách quay lại?',
    options:[{k:'a',t:'Đếm tổng số khách ngủ quên đã quay lại trong tháng gửi tin'},{k:'b',t:'Giữ một nhóm nhỏ không nhận tin, so tỉ lệ quay lại hai nhóm'},
             {k:'c',t:'Hỏi nhân viên lễ tân cảm nhận spa có đông hơn tháng trước'},{k:'d',t:'Xem số lượt mở tin cao hay thấp so với các đợt gửi trước'}],
    answer:'b', why:{a:'Một số khách tự quay lại dù không nhận tin; con số tổng bị thổi phồng.',
      b:'Đúng. Nhóm không nhận tin cho biết mức nền; phần chênh là tác dụng của chiến dịch.',
      c:'Cảm nhận không tách được tác dụng của tin với mùa vụ.',
      d:'Mở tin không phải quay lại mua.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn08-08', skill:'measure', read:'7 phút', t:'Một khách, bốn hồ sơ: dữ liệu nằm rải rác thì làm sao?',
  situation:'Một thương hiệu đồ gia dụng bán ở cửa hàng, Shopee, website và nhận đơn qua Zalo. Chị Hạnh mua ở cả bốn nơi, nên hệ thống có bốn hồ sơ khác nhau với tên viết khác nhau. Mỗi kênh đều coi chị là khách mua một lần, và chị nhận cùng một ưu đãi “khách mới” tới ba lần.',
  concept:{ name:'Gộp hồ sơ khách về một mối',
    body:'Khi dữ liệu nằm ở nhiều nơi, mỗi nơi chỉ thấy một mảnh của khách. Hậu quả: đếm dư số khách, đánh giá sai giá trị khách, và gửi tin mâu thuẫn. Cách bắt đầu không cần hệ thống lớn: chọn <b>một khoá chung</b> (thường là số điện thoại), đưa dữ liệu các kênh về một bảng, gộp các dòng trùng khoá, và quy định từ nay mọi kênh ghi số điện thoại theo cùng một định dạng. Lưu ý: dữ liệu từ sàn thương mại điện tử có thể bị giới hạn theo chính sách của sàn.' },
  example:'Gộp theo số điện thoại chuẩn hoá (bỏ dấu cách, đổi +84 thành 0): 20.000 hồ sơ còn 14.000 khách thật. Chị Hạnh hoá ra đã mua 6 lần, tổng 9 triệu — thuộc nhóm giá trị cao chứ không phải bốn khách lẻ. Từ đó chị nhận tin cảm ơn khách thân thiết thay vì mã “khách mới”.',
  takeaway:'Chọn một khoá chung, gộp hồ sơ, rồi mới đếm khách và chia nhóm.',
  apply:'Liệt kê mọi nơi bạn đang lưu thông tin khách. Nói trong 60 giây: khoá chung bạn sẽ dùng là gì và nơi nào khó gộp nhất.',
  mistakes:['Cộng số khách của từng kênh lại và gọi đó là tổng số khách.','Để mỗi kênh ghi số điện thoại theo một kiểu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi cộng số khách của bốn kênh, con số thường lệch thế nào so với thực tế?',
    options:[{k:'a',t:'Thấp hơn thực tế vì mỗi kênh đều bỏ sót một số khách vãng lai'},{k:'b',t:'Bằng đúng thực tế vì mỗi kênh có tập khách hoàn toàn riêng biệt'},
             {k:'c',t:'Không đoán được, vì mỗi kênh dùng một phần mềm khác nhau'},{k:'d',t:'Cao hơn thực tế vì cùng một người bị đếm ở nhiều kênh'}],
    answer:'d', why:{a:'Có bỏ sót, nhưng đếm trùng thường lớn hơn nhiều với khách mua đa kênh.',
      b:'Khách mua ở nhiều nơi là chuyện phổ biến; tập khách chồng lên nhau.',
      c:'Phần mềm khác nhau là lý do phải gộp, nhưng hướng lệch vẫn đoán được: đếm dư.',
      d:'Đúng. Một khách mua ở ba kênh thành ba khách trong tổng cộng.'} },
  { type:'mcq', stem:'Bạn bắt đầu gộp dữ liệu với nguồn lực ít. Bạn chọn làm gì đầu tiên?',
    options:[{k:'a',t:'Mua ngay một hệ thống CRM đắt tiền có tích hợp sẵn mọi kênh bán'},{k:'b',t:'Chọn số điện thoại làm khoá, chuẩn hoá định dạng, gộp trong một bảng'},
             {k:'c',t:'Chỉ giữ dữ liệu kênh bán nhiều nhất, bỏ dữ liệu các kênh còn lại'},{k:'d',t:'Gộp theo tên khách vì tên là thông tin kênh nào cũng có sẵn'}],
    answer:'b', why:{a:'Công cụ đắt không sửa được nếu chưa có khoá chung và quy tắc ghi dữ liệu.',
      b:'Đúng. Một khoá chung và định dạng thống nhất là nền cho mọi thứ sau.',
      c:'Bỏ kênh khác là mất bức tranh đầy đủ về khách mua đa kênh.',
      d:'Tên viết nhiều kiểu và trùng nhau rất nhiều; là khoá kém.'} },
  { type:'calc', stem:'Bốn kênh cộng lại có 20.000 hồ sơ. Gộp theo số điện thoại còn 14.000 khách thật. Bao nhiêu phần trăm hồ sơ ban đầu là trùng lặp?',
    unit:'%', ans:30, tol:0.1, wrong:[[42.9,'SAI_MAU_SO'],[70,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Hồ sơ trùng = 20.000 − 14.000 = 6.000.','Tỉ lệ = 6.000 ÷ 20.000 = <b>30%</b>.'] },
  { type:'mcq', stem:'Vì sao “0901 234 567” và “+84901234567” cần được chuẩn hoá trước khi gộp?',
    options:[{k:'a',t:'Để số điện thoại trông đẹp và dễ đọc hơn trong báo cáo'},{k:'b',t:'Vì nhà mạng yêu cầu định dạng này khi gửi tin nhắn thương hiệu'},
             {k:'c',t:'Máy sẽ coi hai chuỗi khác nhau là hai khách, dù là một người'},{k:'d',t:'Vì số có +84 là số nước ngoài, cần tách riêng khỏi khách nội'}],
    answer:'c', why:{a:'Đẹp không phải lý do; gộp đúng mới là lý do.',
      b:'Đây là chuyện gộp dữ liệu nội bộ, không phải yêu cầu gửi tin.',
      c:'Đúng. Không chuẩn hoá thì cùng một người vẫn thành nhiều hồ sơ.',
      d:'+84 là mã Việt Nam; đó vẫn là số trong nước.'} },
  { type:'mcq', stem:'Sau khi gộp, chị Hạnh có 6 lần mua, tổng 9 triệu. Tin nào nên gửi cho chị?',
    options:[{k:'a',t:'Lời cảm ơn khách thân thiết, gợi ý món hợp với đồ chị đã mua'},{k:'b',t:'Mã giảm 30% cho khách mới để chị mua đơn đầu tiên ở website'},
             {k:'c',t:'Chuỗi tin đánh thức khách ngủ quên kèm mã giảm giá sâu hơn'},{k:'d',t:'Không gửi gì, vì chị đã mua đủ nhiều rồi nên không cần nhắc thêm'}],
    answer:'a', why:{a:'Đúng. Hồ sơ gộp cho thấy chị là khách giá trị cao; tin phải phản ánh điều đó.',
      b:'Gọi chị là khách mới cho thấy bạn không nhận ra chị.',
      c:'Chị vẫn mua đều qua các kênh, không phải khách ngủ quên.',
      d:'Khách giá trị cao là nhóm đáng chăm sóc nhất.'} },
  { type:'mcq', stem:'Tình huống mới: một phòng khám nha có hồ sơ giấy ở quầy và lịch hẹn trên Zalo. Bước hợp lý đầu tiên là gì?',
    options:[{k:'a',t:'Chụp ảnh toàn bộ hồ sơ giấy lưu vào điện thoại của lễ tân'},{k:'b',t:'Bỏ lịch hẹn Zalo, bắt mọi bệnh nhân gọi điện để đặt lịch hẹn'},
             {k:'c',t:'Tạo nhóm Zalo chung cho mọi bệnh nhân để quản lý một nơi'},{k:'d',t:'Lập một bảng dùng số điện thoại làm khoá cho cả hai nguồn'}],
    answer:'d', why:{a:'Ảnh chụp không tìm kiếm hay gộp được, lại dễ lộ thông tin.',
      b:'Bỏ kênh khách đang quen dùng làm giảm tiện lợi.',
      c:'Nhóm chung làm lộ thông tin bệnh nhân cho nhau — rất rủi ro.',
      d:'Đúng. Một khoá chung giúp nối hai nguồn mà không đổi thói quen khách.'} },
  { type:'mcq', stem:'Dữ liệu từ sàn thương mại điện tử thường khó gộp. Cách xử lý hợp lý là?',
    options:[{k:'a',t:'Nhắn riêng khách trên sàn xin số, hứa ưu đãi nếu mua ngoài sàn'},{k:'b',t:'Đọc kỹ chính sách của sàn; mời khách tự tham gia OA qua kênh được phép'},
             {k:'c',t:'Chép số điện thoại trên phiếu giao hàng vào danh sách gửi tin'},{k:'d',t:'Bỏ hẳn khách trên sàn ra khỏi mọi phân tích dữ liệu khách hàng'}],
    answer:'b', why:{a:'Kéo khách ra khỏi sàn có thể vi phạm chính sách sàn.',
      b:'Đúng. Tôn trọng quy định sàn và để khách tự chọn tham gia.',
      c:'Số trên phiếu giao hàng được cung cấp để giao hàng, không phải để nhận quảng cáo.',
      d:'Vẫn có thể phân tích đơn trên sàn ở mức tổng; bỏ hẳn là mất thông tin.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kn08-09', skill:'comm', read:'6 phút', t:'File khách hàng gửi qua Zalo cho cả nhóm: có vấn đề gì?',
  situation:'Ở một chuỗi cửa hàng điện thoại, quản lý gửi file Excel 30.000 khách — tên, số điện thoại, địa chỉ, món đã mua — vào nhóm Zalo 40 nhân viên để “ai cần thì gọi chăm sóc”. Vài tháng sau, khách phản ánh nhận cuộc gọi chào bán từ một cửa hàng khác, biết cả món họ vừa mua.',
  concept:{ name:'Bảo vệ dữ liệu khách như tài sản',
    body:'Dữ liệu khách chỉ nên dùng cho <b>mục đích khách đã đồng ý</b>, và chỉ người cần mới được xem. Những nguyên tắc chung: thu vừa đủ, phân quyền theo vai trò, không gửi file qua kênh chat, xoá dữ liệu không còn cần, và có cách để khách xin ngừng nhận tin hoặc xoá thông tin. Nhiều nước, trong đó có Việt Nam, có quy định về dữ liệu cá nhân; chi tiết cụ thể nên hỏi người hiểu pháp lý. Dù luật thế nào, lộ dữ liệu là mất lòng tin của khách.' },
  example:'Chuỗi thu hồi file, chuyển dữ liệu vào phần mềm bán hàng có tài khoản riêng cho từng nhân viên. Nhân viên cửa hàng chỉ thấy khách của cửa hàng mình, không tải được toàn bộ danh sách. Mọi lần xuất file phải được quản lý duyệt và có ghi lại. Khi nhân viên nghỉ việc, tài khoản bị khoá ngay trong ngày.',
  takeaway:'Ai cần mới được xem, dùng đúng mục đích khách đã đồng ý, không gửi file qua chat.',
  apply:'Nói trong 60 giây: hiện tại bao nhiêu người trong đội bạn có thể tải toàn bộ danh sách khách, và bạn sẽ thu hẹp lại thế nào.',
  mistakes:['Gửi file khách hàng qua nhóm chat cho tiện.','Không khoá quyền truy cập khi nhân viên nghỉ việc.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lộ dữ liệu khách thường bắt nguồn từ đâu nhất ở doanh nghiệp nhỏ?',
    options:[{k:'a',t:'Hacker chuyên nghiệp tấn công máy chủ bằng kỹ thuật phức tạp'},{k:'b',t:'Lỗi bảo mật của chính phần mềm Zalo hoặc của nhà mạng di động'},
             {k:'c',t:'Khách hàng tự đăng thông tin cá nhân của mình lên mạng xã hội'},{k:'d',t:'Cách làm việc nội bộ lỏng lẻo: gửi file, dùng chung tài khoản'}],
    answer:'d', why:{a:'Có xảy ra, nhưng với doanh nghiệp nhỏ, lỗ hổng lớn hơn thường ở cách làm việc.',
      b:'Vấn đề không nằm ở ứng dụng mà ở việc đưa cả danh sách vào nhóm chat.',
      c:'Khách công khai thông tin của họ không phải là bạn làm lộ dữ liệu.',
      d:'Đúng. File đi qua chat và tài khoản dùng chung là nguồn rò rỉ phổ biến.'} },
  { type:'mcq', stem:'Bạn là quản lý vừa phát hiện file đã nằm trong nhóm 40 người. Bạn làm gì trước?',
    options:[{k:'a',t:'Thu hồi file, chuyển dữ liệu vào hệ thống có phân quyền theo người'},{k:'b',t:'Nhắc nhóm là không được chia sẻ ra ngoài rồi để file như cũ'},
             {k:'c',t:'Đổi tên file thành tên khác để người ngoài khó đoán nội dung'},{k:'d',t:'Chờ xem có khách phàn nàn thêm không rồi mới quyết định xử lý'}],
    answer:'a', why:{a:'Đúng. Ngăn rò tiếp và đặt quyền truy cập theo nhu cầu công việc.',
      b:'Lời nhắc không ngăn được ai đã tải về.',
      c:'Đổi tên không bảo vệ gì nội dung bên trong.',
      d:'Chờ thì dữ liệu vẫn tiếp tục bị dùng sai.'} },
  { type:'calc', stem:'Chuỗi có 10 cửa hàng, mỗi cửa hàng 3.000 khách. Nếu mỗi nhân viên chỉ xem khách của cửa hàng mình, một nhân viên thấy bao nhiêu phần trăm tổng danh sách so với trước (thấy toàn bộ 30.000)?',
    unit:'%', ans:10, tol:0.05, wrong:[[90,'SAI_TINH_TOAN'],[3000,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN','NHAM_SO_TUYET_DOI'],
    steps:['Tổng danh sách = 10 × 3.000 = 30.000 khách.','Một nhân viên thấy 3.000 ÷ 30.000 = <b>10%</b> — nếu một tài khoản bị lộ, thiệt hại nhỏ hơn mười lần.'] },
  { type:'mcq', stem:'Nguyên tắc “thu vừa đủ” nghĩa là gì với form đăng ký thành viên?',
    options:[{k:'a',t:'Hỏi càng nhiều trường càng tốt để sau này có dữ liệu mà phân tích'},{k:'b',t:'Chỉ hỏi thông tin thật sự cần cho mục đích đã nói với khách'},
             {k:'c',t:'Không hỏi gì cả, chỉ cho khách bấm nút đăng ký là đủ dùng'},{k:'d',t:'Hỏi đủ số căn cước để xác minh mỗi khách chỉ có một tài khoản'}],
    answer:'b', why:{a:'Thu thừa làm tăng rủi ro khi lộ và làm khách ngại điền.',
      b:'Đúng. Mỗi trường thông tin phải có lý do gắn với mục đích.',
      c:'Không có thông tin liên hệ thì không có chương trình thành viên.',
      d:'Số căn cước là dữ liệu nhạy cảm, không cần cho tích điểm.'} },
  { type:'mcq', stem:'Một nhân viên kinh doanh nghỉ việc. Việc nào cần làm ngay trong ngày?',
    options:[{k:'a',t:'Gửi email cảm ơn và mời nhân viên đó giới thiệu khách về sau'},{k:'b',t:'Chuyển toàn bộ khách của nhân viên đó sang nhóm khách ngủ quên'},
             {k:'c',t:'Khoá tài khoản truy cập dữ liệu khách của nhân viên đó'},{k:'d',t:'Xoá hết khách do nhân viên đó phụ trách khỏi hệ thống quản lý'}],
    answer:'c', why:{a:'Có thể làm, nhưng không phải việc bảo vệ dữ liệu cấp bách.',
      b:'Khách không ngủ quên chỉ vì nhân viên nghỉ.',
      c:'Đúng. Tài khoản còn mở là cửa để dữ liệu đi theo người ra ngoài.',
      d:'Khách vẫn là khách của công ty; cần giao cho người khác chăm sóc.'} },
  { type:'mcq', stem:'Tình huống mới: đối tác ngân hàng đề nghị “trao đổi danh sách khách” để cùng chào bán. Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đồng ý, vì cả hai bên đều có lợi và khách được thêm lựa chọn'},{k:'b',t:'Đồng ý nhưng chỉ gửi họ tên và số điện thoại, không kèm món đã mua'},
             {k:'c',t:'Đồng ý nếu đối tác cam kết bằng miệng sẽ không làm lộ ra ngoài'},{k:'d',t:'Từ chối trao danh sách; đề xuất mời khách tự đăng ký ưu đãi chung'}],
    answer:'d', why:{a:'Khách chưa đồng ý để thông tin bị chuyển cho bên khác.',
      b:'Tên và số điện thoại vẫn là dữ liệu cá nhân; bớt trường không làm nó thành hợp lệ.',
      c:'Cam kết miệng không thay được sự đồng ý của khách.',
      d:'Đúng. Để khách tự chọn tham gia thì hợp tác mà không phản bội lòng tin.'} },
  { type:'mcq', stem:'Vì sao bảo vệ dữ liệu là việc của marketer, không chỉ của bộ phận IT?',
    options:[{k:'a',t:'Vì marketer quyết định thu gì, dùng vào đâu, gửi cho ai'},{k:'b',t:'Vì marketer thường giỏi công nghệ hơn nhân viên ở bộ phận IT'},
             {k:'c',t:'Vì luật quy định marketer phải chịu mọi trách nhiệm về dữ liệu'},{k:'d',t:'Vì IT chỉ lo phần cứng, còn dữ liệu nằm ngoài phạm vi của họ'}],
    answer:'a', why:{a:'Đúng. Phần lớn quyết định về dữ liệu khách nằm trong các chiến dịch marketing.',
      b:'Không liên quan tới ai giỏi công nghệ hơn.',
      c:'Không nên khẳng định luật quy định như vậy; trách nhiệm tuỳ tổ chức và quy định cụ thể.',
      d:'IT có vai trò quan trọng về dữ liệu; đây là việc chung.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kn08-10', skill:'measure', read:'7 phút', t:'CRM mang về bao nhiêu tiền thật, hay chỉ ghi công cho đơn tự đến?',
  situation:'Báo cáo tháng của một shop thời trang ghi “Zalo OA và email mang về 180 triệu doanh thu” vì đó là tổng giá trị đơn của khách đã nhận tin trong 7 ngày. Giám đốc hỏi: những khách này vốn mua đều mỗi tháng, nếu không gửi tin thì bao nhiêu người vẫn mua?',
  concept:{ name:'Doanh thu tăng thêm nhờ nhóm đối chứng',
    body:'Khách cũ vốn đã có khả năng quay lại. Nếu ghi mọi đơn của người nhận tin cho kênh CRM, bạn đang ghi công cả những đơn đằng nào cũng có. Cách đo sạch là giữ một <b>nhóm đối chứng</b> ngẫu nhiên (ví dụ 10%) không nhận tin, rồi so doanh thu mỗi khách giữa hai nhóm. Phần chênh nhân với số người nhận mới là <b>doanh thu tăng thêm</b>. Sau đó trừ chi phí gửi và ưu đãi để ra lãi thật.' },
  example:'Shop có 20.000 khách: 18.000 nhận tin, 2.000 không nhận. Nhóm nhận tin chi trung bình 10.000 đồng/khách trong tháng, nhóm đối chứng 7.000 đồng/khách. Doanh thu tăng thêm = (10.000 − 7.000) × 18.000 = 54 triệu, không phải 180 triệu. Chi phí gửi và ưu đãi 12 triệu, vẫn có lời — nhưng quyết định ngân sách giờ dựa trên con số thật.',
  takeaway:'Doanh thu từ CRM là phần chênh so với nhóm không nhận tin, không phải tổng đơn của người nhận.',
  apply:'Nói trong 60 giây: đợt gửi tin tới của bạn sẽ giữ lại nhóm đối chứng bao nhiêu người, chọn thế nào, và so bằng chỉ số gì.',
  mistakes:['Ghi toàn bộ doanh thu của người nhận tin cho kênh CRM.','Chọn nhóm đối chứng là khách ít mua nhất thay vì chọn ngẫu nhiên.'],
  q:[
  { type:'mcq', stem:'Đoán trước: con số 180 triệu trong báo cáo thường thế nào so với doanh thu tăng thêm thật?',
    options:[{k:'a',t:'Thấp hơn thật, vì nhiều khách mua sau 7 ngày không được tính'},{k:'b',t:'Cao hơn thật, vì gồm cả đơn khách vẫn mua dù không nhận tin'},
             {k:'c',t:'Bằng đúng thật, vì mọi đơn đều đến từ người đã nhận tin nhắn'},{k:'d',t:'Không so được vì CRM không bao giờ đo được doanh thu chính xác'}],
    answer:'b', why:{a:'Có thể sót vài đơn muộn, nhưng phần ghi công dư thường lớn hơn nhiều.',
      b:'Đúng. Khách cũ vốn đã mua đều; con số tổng gộp cả phần đó.',
      c:'Nhận tin không có nghĩa tin là nguyên nhân mua.',
      d:'Đo được bằng nhóm đối chứng; không cần bỏ cuộc.'} },
  { type:'mcq', stem:'Bạn chuẩn bị đợt gửi tin tháng sau. Bạn chọn cách đo nào?',
    options:[{k:'a',t:'Chọn 2.000 khách ít mua nhất làm nhóm không nhận tin để đỡ phí'},{k:'b',t:'Đếm đơn có dùng mã giảm giá trong tin và coi đó là doanh thu kênh'},
             {k:'c',t:'Giữ ngẫu nhiên 10% khách không nhận tin, so doanh thu mỗi khách'},{k:'d',t:'So doanh thu tháng này với tháng trước để xem kênh CRM tạo ra gì'}],
    answer:'c', why:{a:'Nhóm ít mua sẵn sẽ chi ít hơn, làm hiệu quả kênh bị thổi phồng.',
      b:'Nhiều khách vốn sẽ mua cũng dùng mã; mã không chứng minh tin là nguyên nhân.',
      c:'Đúng. Ngẫu nhiên giúp hai nhóm giống nhau, phần chênh là tác dụng của tin.',
      d:'Hai tháng khác nhau về mùa vụ và khuyến mãi, không tách được tác dụng.'} },
  { type:'calc', stem:'18.000 khách nhận tin chi trung bình 10.000 đồng/khách; nhóm đối chứng chi 7.000 đồng/khách. Chi phí gửi và ưu đãi là 12 triệu đồng. Lãi tăng thêm trên doanh thu (sau khi trừ chi phí đó) là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:42, tol:0.1, wrong:[[168,'QUEN_TRU_CHI_PHI_QC'],[54,'QUEN_CHI_PHI_KHUYEN_MAI']], errors:['QUEN_TRU_CHI_PHI_QC','QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Doanh thu tăng thêm = (10.000 − 7.000) × 18.000 = 54.000.000 đồng = 54 triệu.','Trừ chi phí: 54 − 12 = <b>42 triệu đồng</b>.'] },
  { type:'mcq', stem:'Vì sao nhóm đối chứng phải được chọn ngẫu nhiên?',
    options:[{k:'a',t:'Để hai nhóm giống nhau, chênh lệch chỉ đến từ việc nhận tin'},{k:'b',t:'Để tiết kiệm công sức, vì chọn tay theo tiêu chí thì rất mất thời gian'},
             {k:'c',t:'Vì phần mềm gửi tin chỉ cho phép chia nhóm theo cách ngẫu nhiên'},{k:'d',t:'Để khách không phàn nàn là mình bị bỏ rơi khỏi đợt khuyến mãi'}],
    answer:'a', why:{a:'Đúng. Ngẫu nhiên loại bỏ khác biệt có sẵn giữa hai nhóm.',
      b:'Tiết kiệm công không phải lý do chính.',
      c:'Nhiều phần mềm cho chia theo tiêu chí; ngẫu nhiên là lựa chọn phương pháp.',
      d:'Khách thường không biết mình thuộc nhóm nào; đây không phải lý do.'} },
  { type:'mcq', stem:'Nhóm đối chứng 10% làm shop “mất” một phần doanh thu tiềm năng. Đánh đổi này có đáng?',
    options:[{k:'a',t:'Không đáng, vì mọi khách đều nên nhận tin để tối đa doanh thu ngay'},{k:'b',t:'Chỉ đáng khi kênh đang lỗ, còn kênh có lời thì không cần kiểm tra'},
             {k:'c',t:'Chỉ đáng với doanh nghiệp lớn có trên một triệu khách hàng cũ'},{k:'d',t:'Đáng, vì một phần nhỏ doanh thu đổi lấy con số thật để phân bổ tiền'}],
    answer:'d', why:{a:'Không có đối chứng thì bạn có thể đang chi sai hàng chục triệu mà không biết.',
      b:'Không đo thì không biết kênh lời hay lỗ.',
      c:'Vài nghìn khách đã đủ để thấy chênh lệch rõ.',
      d:'Đúng. Chi phí nhỏ để có căn cứ cho mọi quyết định ngân sách sau này.'} },
  { type:'mcq', stem:'Tình huống mới: nhóm nhận tin chi 8.000 đồng/khách, nhóm đối chứng chi 8.100 đồng/khách. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Kênh đang tốt vì doanh thu mỗi khách vẫn ở mức 8.000 đồng'},{k:'b',t:'Tin nhắn đang làm khách bực nên họ mua ít đi, phải dừng kênh ngay'},
             {k:'c',t:'Đợt tin này gần như không tạo thêm doanh thu; cần xem lại'},{k:'d',t:'Nhóm đối chứng bị chọn sai nên phải bỏ kết quả và đo lại từ đầu'}],
    answer:'c', why:{a:'Con số tuyệt đối không nói gì; phải so với nhóm đối chứng.',
      b:'Chênh 100 đồng rất nhỏ, có thể do ngẫu nhiên; chưa đủ để kết luận tin gây hại.',
      c:'Đúng. Không có chênh lệch thì chi phí gửi không mang về gì; đổi nội dung hoặc người nhận.',
      d:'Không có dấu hiệu chọn sai; kết quả không như ý không phải lý do bỏ số liệu.'} },
  { type:'mcq', stem:'Nên báo cáo gì cho giám đốc sau đợt đo này?',
    options:[{k:'a',t:'Tổng doanh thu 180 triệu của người nhận tin để thể hiện thành tích'},{k:'b',t:'Doanh thu tăng thêm, chi phí, lãi còn lại, và cách chọn đối chứng'},
             {k:'c',t:'Chỉ tỉ lệ mở tin và tỉ lệ bấm vì đó là số của riêng kênh CRM'},{k:'d',t:'Số khách mới đăng ký nhận tin trong tháng như thước đo tăng trưởng'}],
    answer:'b', why:{a:'Con số tổng thổi phồng và dẫn tới quyết định ngân sách sai.',
      b:'Đúng. Đủ để giám đốc tin con số và quyết định tiếp tục hay điều chỉnh.',
      c:'Mở và bấm là chỉ số giữa phễu, không phải tiền.',
      d:'Số đăng ký là đầu vào, không phải kết quả doanh thu.'} }
  ] }

] });
